def copy_city_to_cities(apps, schema_editor):
    # Sprint 84: ogni ricerca esistente diventa "paese + 1 città", senza
    # perderne nessuna. Un paese vuoto si ricava dalle altre ricerche con la
    # stessa città (es. "Zurich" → "Switzerland"); se non è ricavabile resta
    # vuoto e la ricerca va completata alla prossima modifica.
    SavedSearch = apps.get_model("searches", "SavedSearch")
    known = {}
    for search in SavedSearch.objects.exclude(country="").exclude(city=""):
        known.setdefault(search.city.casefold(), search.country)
    for search in SavedSearch.objects.all():
        search.cities = [search.city] if search.city else []
        if not search.country and search.city:
            search.country = known.get(search.city.casefold(), "")
        search.save(update_fields=["cities", "country"])


def copy_cities_to_city(apps, schema_editor):
    SavedSearch = apps.get_model("searches", "SavedSearch")
    for search in SavedSearch.objects.all():
        search.city = search.cities[0] if search.cities else ""
        search.save(update_fields=["city"])


